workflow.ts.js:
import { workflow, job, step,          } from "@kiln/sdk";






const targets           = [
  { os: "linux", arch: "amd64" },
  { os: "macos", arch: "arm64" },
];

function build(t        )      {
  return job({
    "runs-on": `${t.os}/${t.arch}`,
    steps: [step({ run: "cargo build --release" })],
  });
}

export default workflow({
  name: "ci",
  on: { push: { branches: ["main"] } },
  jobs: Object.fromEntries(targets.map((t)                => [`build-${t.os}`, build(t)])),
})                 ;
